/// <reference lib="webworker" />

interface IndexedRow { id: string; search: string; values: Record<string, string> }
type Request =
  | { type: 'init'; rows: IndexedRow[] }
  | { type: 'query'; requestId: number; query: string; sortKey: string; ascending: boolean };

const scope = self as DedicatedWorkerGlobalScope;
let rows: IndexedRow[] = [];
const collator = new Intl.Collator(undefined, { numeric: true });

scope.onmessage = (event: MessageEvent<Request>) => {
  const message = event.data;
  if (message.type === 'init') {
    rows = message.rows;
    return;
  }
  const direction = message.ascending ? 1 : -1;
  const matches = message.query ? rows.filter((row) => row.search.includes(message.query)) : [...rows];
  matches.sort((a, b) => collator.compare(a.values[message.sortKey] ?? '', b.values[message.sortKey] ?? '') * direction);
  scope.postMessage({ type: 'result', requestId: message.requestId, ids: matches.map((row) => row.id) });
};
